// --- validator ---
export const CATEGORIES=['bank','pension','insurer','corporate_investor','pe_sponsor','individual'];
export const ROLE_LABELS={direct_equity_ownership:'Own-account equity interest',beneficial_ownership:'Disclosed beneficial ownership',record_ownership:'Record holder',fund_holding:'Fund portfolio holding',managed_holding:'Asset management for clients (fiduciary)',custody:'Custodian or nominee',manages_fund:'Asset manager',gp_chain_link:'Sponsor control chain',control_assertion:'Source-stated control',governs:'Governing organization',beneficiaries_of:'Beneficiaries',subsidiary_of:'Subsidiary of'};
export const EQUITY=['direct_equity_ownership','beneficial_ownership','record_ownership','fund_holding'];
const ROLE_ONLY=['managed_holding','custody','manages_fund','gp_chain_link','control_assertion','governs','beneficiaries_of','subsidiary_of'];
// [subject kinds, object kinds]. Sponsors, general partners and beneficiaries can never be the subject of an equity claim.
const ENDS={
  direct_equity_ownership:['bank insurer corporate pension_fund holding_vehicle individual','issuer'],
  beneficial_ownership:['bank insurer corporate pension_fund holding_vehicle individual','issuer'],
  record_ownership:['holding_vehicle custodian insurer corporate bank asset_manager','issuer'],
  fund_holding:['pension_fund pe_fund','fund_account issuer'],
  managed_holding:['asset_manager bank','issuer fund_account'],
  custody:['custodian bank asset_manager','issuer fund_account'],
  manages_fund:['asset_manager pe_manager','fund_account pension_fund pe_fund'],
  gp_chain_link:['pe_sponsor pe_general_partner','pe_general_partner pe_fund holding_vehicle'],
  control_assertion:['corporate bank insurer pe_sponsor pe_general_partner','holding_vehicle pe_general_partner'],
  governs:['governing_body','pension_fund'],
  beneficiaries_of:['beneficiary_class','pension_fund'],
  subsidiary_of:['asset_manager bank insurer holding_vehicle corporate','bank insurer corporate pe_sponsor']
};
const KINDS=['bank','insurer','corporate','pension_fund','governing_body','beneficiary_class','asset_manager','custodian','fund_account','pe_sponsor','pe_manager','pe_general_partner','pe_fund','holding_vehicle','issuer','individual'];
const CAPACITY={direct_equity_ownership:['own_account','general_account'],beneficial_ownership:['beneficial_attribution','own_account','general_account'],record_ownership:['record_title'],fund_holding:['fund_portfolio']};
const GP_ROLES=['sole_shareholder','sole_member','general_partner','managing_member'];
// Individuals carry only a name and the public capacity that makes the holding investment-relevant. Personal-profile fields and family/home wording are rejected.
const PERSONAL_KEY=/^(address|street|city|postcode|zip|birth|birthDate|dateOfBirth|age|nationality|citizenship|residence|domicile|family|spouse|children|relatives|netWorth|wealth|biography|photo|image|email|phone|gender|religion)$/i;
const PERSONAL_TEXT=/\b(wife|husband|spouse|son|daughter|children|divorce|born|resides|residence|home address|net worth|birthday)\b|\b\d{1,5}\s+(?:[A-Z][\w.]*\s+){0,3}(?:street|avenue|road|boulevard|drive|lane)\b/i;
const HOSTS=['www.sec.gov','www.frtib.gov','www.tsp.gov','www.govinfo.gov'];
const INT=/^\d+$/,DEC=/^\d+(\.\d+)?$/,ISIN=/\b[A-Z]{2}[A-Z0-9]{9}\d\b/;
const keys=(row,allowed)=>{if(!row||typeof row!=='object'||Array.isArray(row)||Object.keys(row).sort().join('|')!==allowed.split(' ').sort().join('|'))throw new Error('Unexpected holders fields');};
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&new Date(v).toISOString().slice(0,10)===v;
const text=v=>typeof v==='string'&&v.trim().length>0;
const pct=v=>typeof v==='string'&&DEC.test(v)&&Number(v)<=100;
const fail=m=>{throw new Error(m);};
const strings=v=>Array.isArray(v)?v.flatMap(strings):v&&typeof v==='object'?Object.values(v).flatMap(strings):typeof v==='string'?[v]:[];
function scanKeys(v){if(Array.isArray(v))v.forEach(scanKeys);else if(v&&typeof v==='object')for(const [k,x] of Object.entries(v)){if(PERSONAL_KEY.test(k))fail(`Personal-profile field rejected: ${k}`);scanKeys(x);}}
// Source-stated percentage agrees with its own numerator and denominator to within half a unit of its last digit (a check, never a displayed figure).
export function reconcilesWithinRounding(quantityRaw,denominatorRaw,percentRaw){if(!INT.test(quantityRaw)||!INT.test(denominatorRaw)||!DEC.test(percentRaw)||denominatorRaw==='0')return false;const places=(percentRaw.split('.')[1]||'').length,scale=10n**BigInt(places);
  const p=BigInt(percentRaw.replace('.','')),q=BigInt(quantityRaw)*100n*scale*2n,d=BigInt(denominatorRaw);return q>=(2n*p-1n)*d&&q<=(2n*p+1n)*d;}
// Distinct holder→object equity relationships of one case (several claims can describe one relationship).
export function equityRelationships(data,caseId){return [...new Set(data.claims.filter(c=>c.caseId===caseId&&EQUITY.includes(c.type)).map(c=>`${c.from}>${c.to}`))];}
export function validateHoldersPilot(data){
  keys(data,'schemaVersion coverageLabel cases entities sources claims paths overlaps gaps exclusions');
  if(data.schemaVersion!==1||!['cases','entities','sources','claims','paths','overlaps','gaps','exclusions'].every(k=>Array.isArray(data[k])))fail('Invalid holders schema');
  if(!/^One documented case per holder category/.test(data.coverageLabel)||/complete list|full portfolio|100 ?%/i.test(data.coverageLabel.replace('not a complete list','')))fail('Invalid holders coverage label');
  scanKeys(data);if(ISIN.test(JSON.stringify(data))||/cusip|isin|ticker|portfolioWeight|total/i.test(JSON.stringify(data,(k,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).map(x=>[x,1])):Array.isArray(v)?v:undefined)))fail('Holders pilot must not carry identifiers, weights or totals');
  if(data.claims.length>30)fail('Holders pilot exceeds the 30-claim cap');
  const ids=new Set(),unique=id=>{if(ids.has(id))fail('Duplicate holders id');ids.add(id);};
  const cases=new Map(),entities=new Map(),sources=new Map(),claims=new Map();
  for(const c of data.cases){keys(c,'id category label holderId status snapshot boundary');keys(c.snapshot,'anchorSourceId date label');unique(c.id);
    if(!/^holders-case-[a-z0-9-]+$/.test(c.id)||!CATEGORIES.includes(c.category)||!text(c.label)||!text(c.boundary)||!['documented','source_unavailable'].includes(c.status)||!date(c.snapshot.date)||!text(c.snapshot.label))fail('Invalid holders case');cases.set(c.id,c);}
  if(data.cases.length!==6||new Set(data.cases.map(c=>c.category)).size!==6)fail('Holders pilot needs exactly one case per category');
  for(const s of data.sources){keys(s,'id caseId title url asOf publishedAt retrievedAt reuse excerpt');unique(s.id);const url=new URL(s.url);
    if(!/^holders-src-[a-z0-9-]+$/.test(s.id)||!cases.has(s.caseId)||!text(s.title)||!text(s.excerpt)||!text(s.reuse)||url.protocol!=='https:'||url.username||url.password||!HOSTS.includes(url.hostname)||!date(s.retrievedAt)||(s.asOf!==null&&(!date(s.asOf)||s.asOf>s.retrievedAt))||(s.publishedAt!==null&&(!date(s.publishedAt)||s.publishedAt>s.retrievedAt||(s.asOf&&s.asOf>s.publishedAt))))fail('Invalid holders source');sources.set(s.id,s);}
  for(const c of data.cases){const a=sources.get(c.snapshot.anchorSourceId);if(a?.caseId!==c.id||(a.asOf&&a.asOf!==c.snapshot.date))fail('Case snapshot must match its anchor source');}
  for(const e of data.entities){keys(e,e?.kind==='individual'?'id caseId name kind publicCapacity':'id caseId name kind');unique(e.id);
    if(!/^holders-e-[a-z0-9-]+$/.test(e.id)||!cases.has(e.caseId)||!text(e.name)||!KINDS.includes(e.kind))fail('Invalid holders entity');
    if(e.kind==='individual'&&(cases.get(e.caseId).category!=='individual'||!text(e.publicCapacity)))fail('Individuals belong only in the individual case');entities.set(e.id,e);}
  for(const c of data.cases)if(entities.get(c.holderId)?.caseId!==c.id)fail('Case holder must be an entity of the case');
  for(const c of data.claims){
    keys(c,'id caseId type from to measure stake capacity form powers sourceRole note sourceId locator excerpt asOf');unique(c.id);keys(c.stake,'status reason');
    const ends=ENDS[c.type],from=entities.get(c.from),to=entities.get(c.to),src=sources.get(c.sourceId);
    if(!/^holders-claim-[a-z0-9-]+$/.test(c.id)||!ends||!cases.has(c.caseId)||from?.caseId!==c.caseId||to?.caseId!==c.caseId||src?.caseId!==c.caseId||!text(c.locator)||!text(c.excerpt)||(c.note!==null&&!text(c.note)))fail('Invalid holders claim');
    if(!ends[0].split(' ').includes(from.kind)||!ends[1].split(' ').includes(to.kind))fail(`Role ${c.type} cannot run from ${from.kind} to ${to.kind}`);
    if(!date(c.asOf)||c.asOf>(src.publishedAt??src.retrievedAt))fail('Invalid holders claim date');
    if((c.type==='gp_chain_link')!==(c.sourceRole!==null)||(c.sourceRole!==null&&!GP_ROLES.includes(c.sourceRole)))fail('Invalid sponsor chain role');
    if(c.measure!==null){keys(c.measure,'votingPowerRaw quantityRaw percentRaw percentQualifier percentOf denominatorRaw denominatorDate valueRaw valueUnit valueBasis');const x=c.measure;if(!Object.values(x).every(v=>v===null||typeof v==='string'))fail('Holders measures are strings or null');
      if((x.quantityRaw!==null&&(!INT.test(x.quantityRaw)||x.quantityRaw==='0'))||(x.denominatorRaw!==null&&(!INT.test(x.denominatorRaw)||x.denominatorRaw==='0'||!date(x.denominatorDate)))||(x.denominatorRaw===null&&x.denominatorDate!==null)||(x.votingPowerRaw!==null&&!pct(x.votingPowerRaw))||(x.valueRaw!==null&&(!DEC.test(x.valueRaw)||!text(x.valueUnit)||!text(x.valueBasis)))||(x.valueRaw===null&&(x.valueUnit!==null||x.valueBasis!==null)))fail('Invalid holders measure');
      if(x.percentRaw===null?(x.percentQualifier!==null||x.percentOf!==null||x.denominatorRaw!==null):(!pct(x.percentRaw)||!['stated','approximately'].includes(x.percentQualifier)||!text(x.percentOf)))fail('Invalid holders percentage');
      if(x.percentRaw&&x.quantityRaw&&x.denominatorRaw&&!reconcilesWithinRounding(x.quantityRaw,x.denominatorRaw,x.percentRaw))fail('Stated percentage does not reconcile with its denominator');}
    if(ROLE_ONLY.includes(c.type)){
      if(c.stake.status!=='not_applicable'||c.stake.reason!==null||c.capacity!=='role_only'||c.form!==null||c.powers!==null)fail('A role claim carries no ownership stake');
      if(c.measure!==null&&(c.type!=='managed_holding'||c.measure.percentRaw!==null||c.measure.valueRaw!==null||c.measure.votingPowerRaw!==null||c.measure.quantityRaw===null))fail('A role claim carries no ownership stake');
    }else{
      if(!CAPACITY[c.type].includes(c.capacity)||!['direct','indirect','not_stated'].includes(c.form))fail('Equity claim needs a source-stated capacity and form');
      if(c.stake.status==='known'){if(!c.measure?.percentRaw||c.stake.reason!==null)fail('Known stake needs a source-stated percentage');}
      else if(c.stake.status!=='unknown'||!text(c.stake.reason)||c.measure?.percentRaw)fail('Unknown stake stays null with a reason');
      if(c.powers!==null){keys(c.powers,'votingSole votingShared dispositiveSole dispositiveShared');if(!Object.values(c.powers).every(v=>v===null||INT.test(v))||Object.values(c.powers).every(v=>v===null))fail('Invalid holders powers');}
    }
    claims.set(c.id,c);
  }
  const role=(caseId,type,field)=>data.claims.some(c=>c.caseId===caseId&&c.type===type)||data.gaps.some(g=>g.caseId===caseId&&g.field===field);
  const kinds=caseId=>new Set(data.entities.filter(e=>e.caseId===caseId).map(e=>e.kind));
  for(const k of data.cases){
    const own=data.claims.filter(c=>c.caseId===k.id),rels=equityRelationships(data,k.id);
    if(k.status==='source_unavailable'){if(own.length||!data.gaps.some(g=>g.caseId===k.id&&g.status==='source_unavailable'))fail('A gapped category needs an evidence-backed source_unavailable gap and no claims');continue;}
    if(rels.length<1||rels.length>3)fail('Each documented case needs 1–3 equity relationships');
    const holder=entities.get(k.holderId),ks=kinds(k.id);
    if(k.category==='bank'&&(holder.kind!=='bank'||!own.some(c=>c.from===holder.id&&c.capacity==='own_account')||!role(k.id,'managed_holding','asset_management')||!role(k.id,'custody','custody')))fail('Bank case must separate own-account, asset-management and custody roles');
    if(k.category==='pension'&&(holder.kind!=='pension_fund'||!['governing_body','beneficiary_class'].every(x=>ks.has(x))||!own.some(c=>c.type==='governs')||!own.some(c=>c.type==='beneficiaries_of')||!role(k.id,'manages_fund','asset_manager')))fail('Pension case must separate fund, beneficiaries, governing body and asset manager');
    if(k.category==='insurer'&&(holder.kind!=='insurer'||!role(k.id,'managed_holding','third_party_management')||!role(k.id,'__','general_vs_separate_account')&&!own.some(c=>c.from===holder.id&&c.capacity==='general_account')))fail('Insurer case must state insurer-held versus third-party-managed exposure');
    if(k.category==='corporate_investor'&&holder.kind!=='corporate')fail('Corporate case needs a corporate holder');
    if(k.category==='pe_sponsor'){
      if(holder.kind!=='pe_sponsor'||!['pe_general_partner','holding_vehicle','issuer'].every(x=>ks.has(x))||!(ks.has('pe_fund')||role(k.id,'__','pe_fund'))||!(ks.has('pe_manager')||role(k.id,'__','pe_manager')))fail('PE case must keep sponsor, manager, fund, vehicle and portfolio company distinct');
      const path=data.paths.find(p=>p.caseId===k.id&&claims.get(p.claimIds[0])?.from===holder.id&&entities.get(claims.get(p.claimIds.at(-1))?.to)?.kind==='issuer');if(!path)fail('PE case needs a full sponsor-to-company path');}
    if(k.category==='individual'){
      if(holder.kind!=='individual'||own.some(c=>!['beneficial_ownership','direct_equity_ownership'].includes(c.type)))fail('Individual case carries only holding claims');
      if(data.sources.some(s=>s.caseId===k.id&&new URL(s.url).hostname!=='www.sec.gov'))fail('Individual holdings need an SEC filing');
      const words=strings([data.cases.filter(c=>c.id===k.id),data.entities.filter(e=>e.caseId===k.id),data.sources.filter(s=>s.caseId===k.id),own,data.gaps.filter(g=>g.caseId===k.id),data.overlaps.filter(o=>o.caseId===k.id)]);
      if(words.some(w=>PERSONAL_TEXT.test(w)))fail('Individual case must not carry personal-profile text');}
  }
  for(const e of data.entities)if(e.kind==='individual'&&data.claims.some(c=>c.to===e.id))fail('Individuals cannot be objects of claims');
  const inPath=new Set();
  for(const p of data.paths){keys(p,'id caseId claimIds derived note');keys(p.derived,'status percentRaw reason');unique(p.id);
    const chain=p.claimIds.map(id=>claims.get(id));
    if(!/^holders-path-[a-z0-9-]+$/.test(p.id)||chain.length<2||chain.some(c=>c?.caseId!==p.caseId)||!text(p.note))fail('Invalid holders path');
    for(let i=1;i<chain.length;i++)if(chain[i-1].to!==chain[i].from)fail('Path must keep every intermediate');
    if(p.derived.status!=='unknown'||p.derived.percentRaw!==null||!text(p.derived.reason))fail('Indirect paths never imply an undisclosed percentage');p.claimIds.forEach(id=>inPath.add(id));}
  for(const c of data.claims)if(c.type==='gp_chain_link'&&!inPath.has(c.id))fail('Sponsor chain links must sit in a path');
  const groups=[];
  for(const o of data.overlaps){keys(o,'id caseId claimIds reason');unique(o.id);if(!/^holders-overlap-[a-z0-9-]+$/.test(o.id)||o.claimIds.length<2||new Set(o.claimIds).size!==o.claimIds.length||!o.claimIds.every(id=>claims.get(id)?.caseId===o.caseId)||!text(o.reason))fail('Invalid holders overlap');groups.push(new Set(o.claimIds));}
  const eq=data.claims.filter(c=>EQUITY.includes(c.type)||c.type==='managed_holding');
  for(const a of eq)for(const b of eq)if(a.id<b.id&&a.caseId===b.caseId&&a.to===b.to&&!groups.some(g=>g.has(a.id)&&g.has(b.id)))fail('Claims on the same object must sit in an overlap group (never summed)');
  for(const g of data.gaps){keys(g,'id caseId subject field status reason note sourceId');unique(g.id);if(!/^holders-gap-[a-z0-9-]+$/.test(g.id)||entities.get(g.subject)?.caseId!==g.caseId||sources.get(g.sourceId)?.caseId!==g.caseId||!text(g.field)||!['not_disclosed','source_unavailable'].includes(g.status)||!text(g.reason)||!text(g.note))fail('Invalid holders gap');}
  for(const x of data.exclusions){keys(x,'id caseId reason');unique(x.id);if(!/^holders-excl-[a-z0-9-]+$/.test(x.id)||!cases.has(x.caseId)||!text(x.reason))fail('Invalid holders exclusion');}
  return data;
}
validateHoldersPilot(holdersPilot);
